import {
  ADMIN_ROUTES,
  matchAdminRoute,
  type FeatureFlags,
} from "@/lib/admin-routes";
import { buildItems } from "@/lib/admin-sidebar-utils";
import { Permission } from "@/lib/types";
import { Tier } from "@/lib/tiers/types";

const flags: FeatureFlags = {
  vectorDbEnabled: true,
  enableCloud: false,
  tier: Tier.COMMUNITY,
  customAnalyticsEnabled: false,
  hasSubscription: false,
  hooksEnabled: false,
  queryHistoryEnabled: false,
  craftAvailable: false,
};

test("shows one Plugins link for an action manager", () => {
  expect(
    buildItems([Permission.MANAGE_ACTIONS], flags, null).map((item) => ({
      nameId: item.nameId,
      link: item.link,
      disabled: item.disabled,
    }))
  ).toEqual([{ nameId: "plugins", link: "/admin/plugins", disabled: false }]);
});

test("omits Plugins without action management access", () => {
  const links = buildItems([Permission.MANAGE_AGENTS], flags, null).map(
    (item) => item.link
  );
  expect(links).toEqual(["/admin/agents"]);
});

test("shows Decision Models to an LLM manager", () => {
  const links = buildItems([Permission.MANAGE_LLMS], flags, null).map(
    (item) => item.link
  );
  expect(links).toContain("/admin/decision-models");
});

test("marks only Decision Models as a beta entry", () => {
  const betaLinks = buildItems(
    [Permission.FULL_ADMIN_PANEL_ACCESS],
    flags,
    null
  )
    .filter((item) => item.beta)
    .map((item) => item.link);
  expect(betaLinks).toEqual(["/admin/decision-models"]);
});

test("full admins see the canonical link and no legacy action links", () => {
  const actionLinks = buildItems(
    [Permission.FULL_ADMIN_PANEL_ACCESS],
    flags,
    null
  )
    .filter((item) => item.sectionId === "agentsAndTools")
    .map((item) => item.link);
  expect(actionLinks).toEqual(
    expect.arrayContaining(["/admin/agents", "/admin/plugins"])
  );
  expect(actionLinks).not.toContain("/admin/mcp-actions");
  expect(actionLinks).not.toContain("/admin/openapi-actions");
});

test("Craft-enabled admins have one Plugins entry and no separate Apps entry", () => {
  const links = buildItems(
    [Permission.FULL_ADMIN_PANEL_ACCESS],
    { ...flags, craftAvailable: true },
    null
  ).map((item) => item.link);
  expect(links.filter((link) => link === "/admin/plugins")).toHaveLength(1);
  expect(links).not.toContain("/admin/craft/apps");
});

test.each(["/admin/plugins/external-app/7", "/admin/craft/apps"])(
  "retains full-admin authorization for %s",
  (pathname) => {
    expect(matchAdminRoute(pathname)?.requiredPermission).toBe(
      Permission.FULL_ADMIN_PANEL_ACCESS
    );
  }
);

test.each([
  "/admin/plugins",
  "/admin/plugins/mcp/7",
  "/admin/plugins/openapi/7",
  "/admin/mcp-actions",
  "/admin/mcp-actions/new",
  "/admin/mcp-actions/7",
  "/admin/openapi-actions",
])("gates %s with action management permission", (pathname) => {
  expect(matchAdminRoute(pathname)?.requiredPermission).toBe(
    Permission.MANAGE_ACTIONS
  );
});

test("matches canonical plugin details to the Plugins registry entry", () => {
  expect(matchAdminRoute("/admin/plugins/mcp/7")).toBe(ADMIN_ROUTES.PLUGINS);
});

test("shows Skills only to full admins when Craft is available", () => {
  const craftFlags = { ...flags, craftAvailable: true };
  expect(
    buildItems([Permission.FULL_ADMIN_PANEL_ACCESS], craftFlags, null).map(
      (item) => item.link
    )
  ).toContain("/admin/skills");
  expect(
    buildItems([Permission.MANAGE_SKILLS], craftFlags, null).map(
      (item) => item.link
    )
  ).not.toContain("/admin/skills");
});

test("pilot: Discord bot, SCIM, Hooks, Billing and Upgrade plan are not in the sidebar", () => {
  const items = buildItems(
    [Permission.FULL_ADMIN_PANEL_ACCESS],
    { ...flags, hooksEnabled: true, hasSubscription: false },
    null
  );
  const links = items.map((item) => item.link);
  for (const hidden of ["/admin/discord-bot", "/admin/scim", "/admin/hooks", "/admin/billing"]) {
    expect(links).not.toContain(hidden);
  }
  expect(items.map((item) => item.nameId)).not.toContain("upgradePlan");
});

test("redesign order: Overview, then Approvals, with packs under Agents & tools", () => {
  const items = buildItems([Permission.FULL_ADMIN_PANEL_ACCESS], flags, null);
  const sections = [...new Set(items.map((item) => item.sectionId))];
  expect(sections.slice(0, 2)).toEqual(["overview", "approvals"]);
  expect(sections.indexOf("agentsAndTools")).toBeLessThan(sections.indexOf("governance"));
  const packs = items.find((item) => item.link === "/admin/packs");
  expect(packs?.sectionId).toBe("agentsAndTools");
});
